<template><section class="work-panel"><h2>{{ $ui('封面、画廊与介绍视频') }}</h2><p class="store-muted">{{ $ui('图片支持PNG、JPEG、WebP，每张最多5MiB，画廊最多12张；视频支持MP4、WebM，最多50MiB。上传或移除后须经审核才会公开显示。') }}</p><form class="store-form" @submit.prevent="upload"><label>{{ $ui('媒体类型') }}<select v-model="kind"><option value="cover">{{ $ui('封面图') }}</option><option value="gallery">{{ $ui('画廊图片') }}</option><option value="video">{{ $ui('介绍视频') }}</option></select></label><label>{{ $ui('选择文件') }}<input :key="inputKey" type="file" required :accept="kind==='video'?'video/mp4,video/webm':'image/png,image/jpeg,image/webp'" @change="select" /></label><button class="primary-button" :disabled="busy || !file || testMode">{{ $ui(busy?'正在上传…':'上传并提交审核') }}</button></form><p v-if="error" class="form-error" role="alert">{{ $ui(error) }}</p><ProjectMedia :media="media"><template #default="{file:asset}"><button class="secondary-button" :disabled="busy || testMode" @click="remove(asset.id)">{{ $ui('移除并提交审核') }}</button></template></ProjectMedia></section></template>
<script setup lang="ts">
import{ref}from'vue';import{store,type StoreContent,type ProjectMedia as Media}from'@/api/store';import{isTestSession}from'@/api/platform';import ProjectMedia from './ProjectMedia.vue';const props=defineProps<{item:StoreContent;media:Media[]}>(),emit=defineEmits<{changed:[]}>();const kind=ref<Media['kind']>('cover'),file=ref<File>(),busy=ref(false),error=ref(''),inputKey=ref(0),testMode=isTestSession();function select(event:Event){file.value=(event.target as HTMLInputElement).files?.[0];}
async function upload(){if(busy.value||!file.value)return;busy.value=true;error.value='';try{await store.uploadMedia(props.item,kind.value,file.value);file.value=undefined;inputKey.value++;emit('changed');}catch(e){error.value=e instanceof Error?e.message:'媒体上传失败，请重试';}finally{busy.value=false;}}
async function remove(id:string){if(busy.value)return;busy.value=true;error.value='';try{await store.removeMedia(props.item,id);emit('changed');}catch(e){error.value=e instanceof Error?e.message:'媒体移除失败，请重试';}finally{busy.value=false;}}
</script>
